<script setup lang="ts">
// Home page: stats + filterable grid of every topic (data generated by scripts/build-content.mjs)
import { computed, ref } from "vue";
import { withBase } from "vitepress";
import topics from "../../../.generated/topics.json";

const props = defineProps<{
  stats: { guides: number; pdfs: number; topics: number; files: number };
}>();
const q = ref("");
const shown = computed(() => {
  const n = q.value.trim().toLowerCase();
  return n
    ? topics.filter((t: any) => t.title.toLowerCase().includes(n))
    : topics;
});
const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;

function openSearch() {
  // the default theme opens its local search on Ctrl/Cmd + K
  window.dispatchEvent(
    new KeyboardEvent("keydown", { key: "k", ctrlKey: true, bubbles: true }),
  );
}
</script>

<template>
  <section class="topics" aria-labelledby="topics-title">
    <button class="search-cta" type="button" @click="openSearch">
      <i class="i i-magnifying-glass" aria-hidden="true" />
      <span>Search every guide and book</span>
      <kbd>Ctrl K</kbd>
    </button>

    <dl class="stats">
      <div>
        <dt>Topics</dt>
        <dd>{{ props.stats.topics }}</dd>
      </div>
      <div>
        <dt>Guides</dt>
        <dd>{{ props.stats.guides }}</dd>
      </div>
      <div>
        <dt>PDF books</dt>
        <dd>{{ props.stats.pdfs }}</dd>
      </div>
      <div>
        <dt>Other files</dt>
        <dd>{{ props.stats.files }}</dd>
      </div>
    </dl>

    <div class="head">
      <h2 id="topics-title">Browse by topic</h2>
      <label class="filter">
        <span class="sr-only">Filter topics</span>
        <i class="i i-magnifying-glass" aria-hidden="true" />
        <input
          v-model="q"
          type="search"
          placeholder="Filter topics…"
          autocomplete="off"
        />
      </label>
    </div>

    <p class="sr-only" role="status" aria-live="polite">
      {{ plural(shown.length, "topic") }} shown
    </p>

    <ul v-if="shown.length" class="grid">
      <li v-for="t in shown" :key="t.link">
        <a class="card" :href="withBase(t.link)">
          <span class="ico" v-html="t.icon" />
          <span class="body">
            <span class="title">{{ t.title }}</span>
            <span class="meta"
              >{{ plural(t.guides, "guide") }} ·
              {{ plural(t.books, "book") }}</span
            >
          </span>
        </a>
      </li>
    </ul>
    <p v-else class="empty">No topic matches “{{ q }}”.</p>
  </section>
</template>

